use crate::domain::wallet::{WalletStats, WalletTier}; use rust_decimal::Decimal; use rust_decimal_macros::dec;
#[derive(Debug, Clone)] pub struct SmartMoneyThresholds { pub observed_trades: u32, pub qualified_trades: u32, pub qualified_score: Decimal, pub high_confidence_score: Decimal }
impl Default for SmartMoneyThresholds { fn default() -> Self { Self { observed_trades: 5, qualified_trades: 25, qualified_score: dec!(60), high_confidence_score: dec!(75) } } }
pub fn score_wallet(stats: &mut WalletStats, t: &SmartMoneyThresholds) { let sample = Decimal::from(stats.trades.min(100)) / dec!(100); let performance = (stats.win_rate * dec!(25) + stats.avg_return_pct.min(dec!(30)) + stats.median_return_pct.min(dec!(20)) + stats.recent_return_pct.min(dec!(15))).max(Decimal::ZERO); let penalties = stats.max_drawdown_pct.min(dec!(30)) + stats.concentration_pct.max(Decimal::ZERO) * dec!(0.1) + stats.scam_exposure_pct.max(Decimal::ZERO) * dec!(0.5); stats.score = ((performance - penalties).max(Decimal::ZERO) * sample + stats.realized_pnl_usd.max(Decimal::ZERO).min(dec!(10))).min(dec!(100)); stats.tier = if stats.trades >= t.qualified_trades && stats.score >= t.high_confidence_score { WalletTier::HighConfidence } else if stats.trades >= t.qualified_trades && stats.score >= t.qualified_score { WalletTier::Qualified } else if stats.trades >= t.observed_trades { WalletTier::Observed } else { WalletTier::Candidate }; }
#[cfg(test)] mod tests { use super::*; use chrono::Utc; use crate::domain::wallet::WalletTier; fn wallet() -> WalletStats { WalletStats { wallet:"x".into(), entity_id:None, realized_pnl_usd: dec!(50),win_rate:dec!(80),avg_return_pct:dec!(15),median_return_pct:dec!(10),max_drawdown_pct:dec!(5),trades:50,recent_return_pct:dec!(12),concentration_pct:dec!(10),scam_exposure_pct:dec!(0),score:Decimal::ZERO,tier:WalletTier::Candidate,updated_at:Utc::now() } } #[test] fn scores_sample_and_penalizes() { let mut w=wallet(); score_wallet(&mut w,&Default::default()); assert!(w.score > dec!(60)); assert_eq!(w.tier,WalletTier::Qualified); } }
